"""Emit editable Godot scene nodes from hand-authored R01 route polygons."""
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]/'Scene'/'rebuild'
def points(values):
    return ', '.join(str(v) for pair in values for v in pair)

def scene(area, terrain, branches, props, sky):
    lines=['[gd_scene format=3]',f'[node name="R01_A{area:02}" type="Node2D"]']
    def poly(name, vertices, color, collision=False, branch=False):
        lines.extend([f'[node name="{name}" type="'+('StaticBody2D' if collision else 'Node2D')+'" parent="."'+(' groups=["grabbable"]' if collision and not 'Boundary' in name else '')+']'])
        if collision:
            lines.extend(['collision_layer = 2','collision_mask = 0',f'groups = []'] if False else ['collision_layer = 2','collision_mask = 0'])
            # Native nodes are directly editable in the Godot 2D canvas.
            lines.extend([f'[node name="Collision" type="CollisionPolygon2D" parent="{name}"]',f'polygon = PackedVector2Array({points(vertices)})']+(['one_way_collision = true'] if branch else []))
        lines.extend([f'[node name="Surface" type="Polygon2D" parent="{name}"]',f'polygon = PackedVector2Array({points(vertices)})',f'color = Color({color})'])
        if collision:
            lines.extend([f'[node name="TopEdge" type="Line2D" parent="{name}"]',f'points = PackedVector2Array({points(vertices[:-2])})','width = 2.0',f'default_color = Color({"0.76, 0.63, 0.40, 1" if branch else "0.80, 0.84, 0.70, 1"})'])
    poly('Backdrop',[(0,0),(4000,0),(4000,1000),(0,1000)],sky)
    for i,top in enumerate(terrain):
        poly(f'MainRoute_{i:02}',top+[(top[-1][0],950),(top[0][0],950)],'0.39, 0.43, 0.38, 1',True)
    for i,(x,y,w) in enumerate(branches):
        poly(f'Alternative_{i:02}',[(x,y),(x+w,y),(x+w,y+18),(x,y+18)],'0.46, 0.46, 0.36, 1',True,True)
    for i,(x,y,w,h,color) in enumerate(props):
        poly(f'Landmark_{i:02}',[(x,y),(x+w,y),(x+w,y+h),(x,y+h)],color)
    # Foundation edges only at the outer world ends; there are no walls at scene seams.
    if area==1:
        poly('LeftBoundary',[(-25,0),(0,0),(0,950),(-25,950)],'0.2,0.25,0.25,1',True)
    if area==7:
        poly('TemporaryMilestoneBoundary',[(3990,0),(4010,0),(4010,950),(3990,950)],'0.2,0.25,0.25,1',True)
    (ROOT/f'{"R01" if area<=3 else "R02"}_A{area:02}.tscn').write_text('\n\n'.join(lines)+'\n',encoding='utf-8')

